// TEMPORARY DIAGNOSTIC ONLY: no solver mutation; never merge this observer.
fn trace_stage(cloth: &Cloth, substep: usize, outer: usize, phase: &str, x: &[Vec3], velocities: &[Vec3], pm: &[Vec3], pb: &[Vec3], ps: &[Vec3], targets: &[f64], h: f64, contacts: usize, previous_trace: &mut [Vec3]) {
    let mut peak = (0_usize, 0_usize, 0_f64);
    for (index, &vertices) in cloth.input.triangles.iter().enumerate() {
        let values = strain::signed_strains(vertices.map(|v| x[v]), vertices.map(|v| cloth.input.material_uv[v]), cloth.input.triangle_materials[index].grain_angle);
        for (axis, value) in values.into_iter().enumerate() {
            if value.abs() > peak.2.abs() { peak = (index, axis, value); }
        }
    }
    let mut moment = [0.; 3]; let mut ps_moment = [0.; 3]; let mut pm_moment = [0.; 3]; let mut pb_moment = [0.; 3];
    let mut max_delta = (0_f64, 0_usize); let mut pmax = 0_f64; let mut vmax = 0_f64; let mut inertia = 0.;
    for i in 0..x.len() {
        moment = add(moment, mul(x[i], cloth.masses[i]));
        ps_moment = add(ps_moment, mul(ps[i], cloth.masses[i]));
        pm_moment = add(pm_moment, mul(pm[i], cloth.masses[i]));
        pb_moment = add(pb_moment, mul(pb[i], cloth.masses[i]));
        let delta = length(sub(x[i], previous_trace[i]));
        if delta > max_delta.0 { max_delta = (delta, i); }
        pmax = pmax.max(length(ps[i])); vmax = vmax.max(length(velocities[i]));
        inertia += 0.5 * cloth.masses[i] * dot(ps[i], ps[i]);
    }
    let mut gap_max = 0_f64; let mut target_error = 0_f64; let mut potential = 0.;
    for (stitch, &target) in cloth.input.stitches.iter().zip(targets) {
        let gap = length(sub(stitch.a.position(x), stitch.b.position(x)));
        gap_max = gap_max.max(gap); target_error = target_error.max((gap-target).abs());
        if stitch.compliance > 0. { potential += 0.5 * h * h * (gap-target).powi(2) / stitch.compliance; }
    }
    let vertices = cloth.input.triangles[peak.0];
    eprintln!("WF_STAGE\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:?}\t{:?}\t{:?}\t{:?}\t{}\t{}\t{}\t{}\t{:?}\t{:?}\t{:?}\t{:?}\t{}\t{}\t{}",
        substep, outer, phase, peak.0, peak.1, peak.2, max_delta.0, max_delta.1, pmax, moment, ps_moment, pm_moment, pb_moment,
        targets.iter().copied().fold(0_f64, f64::max), gap_max, target_error, contacts, vertices, vertices.map(|v| x[v]), vertices.map(|v| ps[v]), vertices.map(|v| cloth.input.material_uv[v]), inertia, potential, vmax);
    previous_trace.copy_from_slice(x);
}
